REFINED_SCHEMA = "refined"

INGEST = f"{CATALOG}.{INGEST_SCHEMA}"
REFINED = f"{CATALOG}.{REFINED_SCHEMA}"
SERVE_SCHEMA = "serve"

SERVE = f"{CATALOG}.{SERVE_SCHEMA}"
