from pyspark import pipelines as dp
from pyspark.sql import DataFrame
from pyspark.sql.functions import (
    unix_timestamp,
    trunc,
    sum as spark_sum,
    sequence,
    min as spark_min,
    max as spark_max,
    expr,
    explode,
    date_format,
    countDistinct,
    count,
    coalesce,
    col,
    length,
    lit,
    regexp_extract,
    row_number,
    to_date,
    to_timestamp,
    trim,
    upper,
    when,
)
from pyspark.sql.types import LongType
from pyspark.sql.window import Window

VALID_PURCHASE_ORDER_STATUSES = ("CREATED", "CONFIRMED", "DELIVERED", "CANCELLED")
VALID_SALES_ORDER_STATUSES = ("CREATED", "CONFIRMED", "SHIPPED", "DELIVERED", "CANCELLED")
VALID_PRODUCTION_ORDER_STATUSES = ("PLANNED", "IN_PROGRESS", "COMPLETED", "CANCELLED")
VALID_DOWNTIME_REASONS = (
    "MAINTENANCE",
    "POWER_FAILURE",
    "MATERIAL_SHORTAGE",
    "MACHINE_FAILURE",
    "QUALITY_CHECK",
)
# COMMAND ----------
# MAGIC ## Shared transformation helpers
# MAGIC 
# MAGIC Reusable data-quality and cleansing functions for the silver layer.
# COMMAND ----------

def _dedupe_order_columns(df: DataFrame) -> list:
    """
    Build window ordering from ingest metadata columns that exist on the source table.

    bronze_row_id may only be present on transactional order tables (purchase_orders,
    sales_orders). Other sources use updated_at, Fivetran sync metadata, or dropDuplicates.
    """
    order_cols = []
    for column_name in (
        "bronze_row_id",
        "sys_updated_on",
        "updated_at",
        "_fivetran_synced",
        "created_at",
        "sys_created_on",
    ):
        if column_name in df.columns:
            order_cols.append(col(column_name).desc_nulls_last())
    return order_cols


def _dedupe_latest(df: DataFrame, business_key: str) -> DataFrame:
    """Keep the latest row per business key when duplicates exist."""
    order_cols = _dedupe_order_columns(df)
    if not order_cols:
        return df.dropDuplicates([business_key])
    window = Window.partitionBy(business_key).orderBy(*order_cols)
    return (
        df.withColumn("_row_num", row_number().over(window))
        .filter(col("_row_num") == 1)
        .drop("_row_num")
    )


def _dedupe_exact_rows(df: DataFrame, key_columns: list[str]) -> DataFrame:
    """Remove duplicate rows for batch WMS tables, keeping the latest ingest record."""
    order_cols = _dedupe_order_columns(df)
    if not order_cols:
        return df.dropDuplicates(key_columns)
    window = Window.partitionBy(*key_columns).orderBy(*order_cols)
    return (
        df.withColumn("_row_num", row_number().over(window))
        .filter(col("_row_num") == 1)
        .drop("_row_num")
    )


def _trim_string_columns(df: DataFrame, columns: list[str]) -> DataFrame:
    """Trim leading and trailing whitespace on string columns."""
    trimmed = df
    for column_name in columns:
        if column_name in trimmed.columns:
            trimmed = trimmed.withColumn(column_name, trim(col(column_name)))
    return trimmed


def _normalize_status(status_column: str):
    """Map common status variants to canonical ERP values and uppercase the remainder."""
    normalized = trim(col(status_column))
    return (
        when(normalized == "DELIVERD", lit("DELIVERED"))
        .when(normalized.rlike("(?i)^confirmed$"), lit("CONFIRMED"))
        .when(normalized.rlike("(?i)^shipped$"), lit("SHIPPED"))
        .when((normalized == "") | normalized.isNull(), lit(None))
        .otherwise(upper(normalized))
    )


def _parse_bronze_date(column_name: str):
    """Parse source date strings; invalid values become NULL without failing the pipeline."""
    raw = trim(col(column_name))
    iso_prefix = regexp_extract(raw, r"^(\d{4}-\d{2}-\d{2})", 1)
    return coalesce(
        when(raw.rlike(r"^\d{4}-\d{2}-\d{2}$"), to_date(raw, "yyyy-MM-dd")),
        when(raw.rlike(r"^\d{4}-\d{2}-\d{2}T"), to_date(raw, "yyyy-MM-dd'T'HH:mm:ss")),
        when(raw.rlike(r"^\d{2}/\d{2}/\d{4}$"), to_date(raw, "dd/MM/yyyy")),
        when(raw.rlike(r"^\d{2}-[A-Za-z]{3}-\d{4}$"), to_date(raw, "dd-MMM-yyyy")),
        when(length(iso_prefix) > 0, to_date(iso_prefix, "yyyy-MM-dd")),
    )


def _parse_positive_quantity(column_name: str):
    """Cast source quantity values and retain only strictly positive integers."""
    parsed = when(
        trim(col(column_name)).rlike(r"^-?\d+(\.\d+)?$"),
        trim(col(column_name)).cast("double").cast(LongType()),
    )
    return when(parsed > 0, parsed)


def _filter_non_null_key(df: DataFrame, key_column: str) -> DataFrame:
    """Drop rows with missing or blank primary/business identifiers."""
    return df.filter(col(key_column).isNotNull() & (length(col(key_column)) > 0))


def _clean_master_stream(
    source_df: DataFrame,
    business_key: str,
    string_columns: list[str],
) -> DataFrame:
    """Apply silver cleansing rules to ERP master tables."""
    cleaned = _trim_string_columns(source_df, string_columns)
    cleaned = _filter_non_null_key(cleaned, business_key)
    return _dedupe_latest(cleaned, business_key)


def _clean_order_stream(
    source_df: DataFrame,
    business_key: str,
    string_columns: list[str],
    delivery_date_column: str,
    valid_statuses: tuple[str, ...],
) -> DataFrame:
    """Apply silver cleansing rules to ERP purchase and sales orders."""
    cleaned = _trim_string_columns(source_df, string_columns)
    cleaned = _filter_non_null_key(cleaned, business_key)
    cleaned = _dedupe_latest(cleaned, business_key)

    cleaned = (
        cleaned.withColumn("status", _normalize_status("status"))
        .withColumn("order_date", _parse_bronze_date("order_date"))
        .withColumn(delivery_date_column, _parse_bronze_date(delivery_date_column))
        .withColumn("quantity", _parse_positive_quantity("quantity"))
    )

    cleaned = cleaned.filter(col("quantity").isNotNull())

    cleaned = cleaned.withColumn(
        "status",
        when(col("status").isin(*valid_statuses), col("status")).otherwise(upper(col("status"))),
    )

    return cleaned


def _enforce_foreign_key(
    df: DataFrame,
    foreign_key: str,
    master_df: DataFrame,
    master_key: str,
) -> DataFrame:
    """Drop rows whose foreign key is missing from the cleaned master table."""
    valid_keys = master_df.select(master_key).distinct()
    if foreign_key == master_key:
        return df.join(valid_keys, on=foreign_key, how="left_semi")
    return df.join(
        valid_keys,
        df[foreign_key] == valid_keys[master_key],
        how="left_semi",
    )


def _enforce_material_type(
    df: DataFrame,
    materials_df: DataFrame,
    *,
    material_type: str,
) -> DataFrame:
    """Drop rows that reference materials of the wrong type or not in the master list."""
    valid_materials = (
        materials_df.filter(col("material_type") == material_type)
        .select("material_id")
        .distinct()
    )
    return df.join(valid_materials, on="material_id", how="inner")


def _clean_purchase_orders(
    source_df: DataFrame,
    suppliers_df: DataFrame,
    materials_df: DataFrame,
) -> DataFrame:
    """Clean purchase orders and retain only rows with valid supplier and raw material FKs."""
    cleaned = _clean_order_stream(
        source_df,
        business_key="purchase_order_id",
        string_columns=[
            "purchase_order_id",
            "supplier_id",
            "material_id",
            "status",
            "order_date",
            "expected_delivery_date",
            "quantity",
        ],
        delivery_date_column="expected_delivery_date",
        valid_statuses=VALID_PURCHASE_ORDER_STATUSES,
    )
    cleaned = _enforce_foreign_key(cleaned, "supplier_id", suppliers_df, "supplier_id")
    return _enforce_material_type(cleaned, materials_df, material_type="RAW_MATERIAL")


def _clean_sales_orders(
    source_df: DataFrame,
    customers_df: DataFrame,
    materials_df: DataFrame,
) -> DataFrame:
    """Clean sales orders and retain only rows with valid customer and finished-good FKs."""
    cleaned = _clean_order_stream(
        source_df,
        business_key="sales_order_id",
        string_columns=[
            "sales_order_id",
            "customer_id",
            "material_id",
            "status",
            "order_date",
            "requested_delivery_date",
            "quantity",
        ],
        delivery_date_column="requested_delivery_date",
        valid_statuses=VALID_SALES_ORDER_STATUSES,
    )
    cleaned = _enforce_foreign_key(cleaned, "customer_id", customers_df, "customer_id")
    return _enforce_material_type(cleaned, materials_df, material_type="FINISHED_GOOD")


def _clean_inventory_with_masters(
    source_df: DataFrame,
    warehouses_df: DataFrame,
    materials_df: DataFrame,
) -> DataFrame:
    """Clean inventory snapshots and retain only rows with valid warehouse and material FKs."""
    cleaned = _clean_inventory_batch(source_df)
    cleaned = _enforce_foreign_key(cleaned, "warehouse_id", warehouses_df, "warehouse_id")
    return _enforce_foreign_key(cleaned, "material_id", materials_df, "material_id")


def _clean_inventory_batch(source_df: DataFrame) -> DataFrame:
    """Silver rules for Fivetran WMS inventory snapshots."""
    string_columns = ["warehouse_id", "material_id", "quantity", "snapshot_date"]
    cleaned = _trim_string_columns(source_df, string_columns)
    cleaned = cleaned.filter(
        col("warehouse_id").isNotNull()
        & (length(col("warehouse_id")) > 0)
        & col("material_id").isNotNull()
        & (length(col("material_id")) > 0)
        & col("snapshot_date").isNotNull()
        & (length(col("snapshot_date")) > 0)
    )
    cleaned = cleaned.withColumn(
        "quantity",
        _parse_positive_quantity("quantity"),
    )
    cleaned = cleaned.filter(col("quantity").isNotNull())
    cleaned = cleaned.withColumn("snapshot_date", to_date(col("snapshot_date")))
    cleaned = _dedupe_exact_rows(cleaned, ["snapshot_date", "warehouse_id", "material_id"])
    return cleaned


def _clean_inventory_transactions_with_masters(
    source_df: DataFrame,
    warehouses_df: DataFrame,
    materials_df: DataFrame,
) -> DataFrame:
    """Clean inventory transactions and retain only rows with valid warehouse and material FKs."""
    cleaned = _clean_inventory_transactions_batch(source_df)
    cleaned = _enforce_foreign_key(cleaned, "warehouse_id", warehouses_df, "warehouse_id")
    return _enforce_foreign_key(cleaned, "material_id", materials_df, "material_id")


def _clean_inventory_transactions_batch(source_df: DataFrame) -> DataFrame:
    """Silver rules for Fivetran WMS inventory transactions."""
    string_columns = [
        "transaction_id",
        "transaction_date",
        "warehouse_id",
        "material_id",
        "transaction_type",
        "quantity",
        "reference_id",
    ]
    cleaned = _trim_string_columns(source_df, string_columns)
    cleaned = cleaned.filter(
        col("transaction_id").isNotNull()
        & (length(col("transaction_id")) > 0)
        & col("warehouse_id").isNotNull()
        & (length(col("warehouse_id")) > 0)
        & col("material_id").isNotNull()
        & (length(col("material_id")) > 0)
        & col("transaction_type").isNotNull()
        & (length(col("transaction_type")) > 0)
    )
    cleaned = cleaned.withColumn("transaction_type", upper(col("transaction_type")))
    cleaned = cleaned.withColumn("quantity", _parse_positive_quantity("quantity"))
    cleaned = cleaned.filter(col("quantity").isNotNull())
    cleaned = _dedupe_exact_rows(cleaned, ["transaction_id"])
    return cleaned


def _normalize_ingest_column_names(df: DataFrame) -> DataFrame:
    """Rename quoted or case-variant ingest columns to canonical lowercase names."""
    if not df.columns:
        return df
    return df.select(
        *[
            col(field.name).alias(field.name.strip('"').strip("`").lower())
            for field in df.schema.fields
        ]
    )


def _apply_column_aliases(df: DataFrame, aliases: dict[str, list[str]]) -> DataFrame:
    """Map connector-specific column names onto canonical schema fields."""
    normalized = _normalize_ingest_column_names(df)
    for canonical, candidates in aliases.items():
        existing = [name for name in candidates if name in normalized.columns]
        if not existing:
            continue
        normalized = normalized.withColumn(
            canonical,
            coalesce(*[col(name) for name in existing]),
        )
    return normalized


def _parse_bronze_timestamp(column_name: str):
    """Parse source timestamp strings; invalid values become NULL."""
    raw = trim(col(column_name))
    return coalesce(
        when(raw.rlike(r"^\d{4}-\d{2}-\d{2}T"), to_timestamp(raw, "yyyy-MM-dd'T'HH:mm:ss")),
        when(raw.rlike(r"^\d{4}-\d{2}-\d{2} "), to_timestamp(raw, "yyyy-MM-dd HH:mm:ss")),
        when(raw.rlike(r"^\d{4}-\d{2}-\d{2}$"), to_timestamp(raw, "yyyy-MM-dd")),
        when(raw.rlike(r"^\d{2}/\d{2}/\d{4}"), to_timestamp(raw, "dd/MM/yyyy HH:mm:ss")),
    )


def _parse_optional_positive_quantity(column_name: str):
    """Cast optional quantity values and retain only strictly positive integers."""
    parsed = when(
        trim(col(column_name)).rlike(r"^-?\d+(\.\d+)?$"),
        trim(col(column_name)).cast("double").cast(LongType()),
    )
    return when(parsed > 0, parsed)


def _clean_production_orders(
    source_df: DataFrame,
    plants_df: DataFrame,
    materials_df: DataFrame,
) -> DataFrame:
    """Clean production orders from Snowflake ingest.

    Snowflake ingest may expose quoted lowercase columns such as
    `"production_order_id"`; these are normalized before cleansing.
    """
    source_df = _normalize_ingest_column_names(source_df)
    aliases = {
        "production_order_id": ["production_order_id", "PRODUCTION_ORDER_ID"],
        "plant_id": ["plant_id", "PLANT_ID"],
        "material_id": ["material_id", "MATERIAL_ID"],
        "planned_quantity": ["planned_quantity", "PLANNED_QUANTITY"],
        "actual_quantity": ["actual_quantity", "ACTUAL_QUANTITY"],
        "start_date": ["start_date", "START_DATE"],
        "end_date": ["end_date", "END_DATE"],
        "status": ["status", "STATUS"],
    }
    cleaned = _apply_column_aliases(source_df, aliases)
    cleaned = _trim_string_columns(
        cleaned,
        [
            "production_order_id",
            "plant_id",
            "material_id",
            "status",
            "start_date",
            "end_date",
            "planned_quantity",
            "actual_quantity",
        ],
    )
    cleaned = _filter_non_null_key(cleaned, "production_order_id")
    cleaned = _dedupe_latest(cleaned, "production_order_id")
    cleaned = (
        cleaned.withColumn("status", _normalize_status("status"))
        .withColumn("start_date", _parse_bronze_date("start_date"))
        .withColumn("end_date", _parse_bronze_date("end_date"))
        .withColumn("planned_quantity", _parse_positive_quantity("planned_quantity"))
        .withColumn("actual_quantity", _parse_optional_positive_quantity("actual_quantity"))
    )
    cleaned = cleaned.filter(col("planned_quantity").isNotNull())
    cleaned = cleaned.withColumn(
        "status",
        when(col("status").isin(*VALID_PRODUCTION_ORDER_STATUSES), col("status")).otherwise(
            upper(col("status"))
        ),
    )
    cleaned = _enforce_foreign_key(cleaned, "plant_id", plants_df, "plant_id")
    return _enforce_material_type(cleaned, materials_df, material_type="FINISHED_GOOD")


def _clean_production_output(
    source_df: DataFrame,
    production_orders_df: DataFrame,
    materials_df: DataFrame,
) -> DataFrame:
    """Clean production output from Snowflake ingest.

    Snowflake ingest may expose quoted lowercase columns such as
    `"production_output_id"`; these are normalized before cleansing.
    """
    source_df = _normalize_ingest_column_names(source_df)
    aliases = {
        "production_output_id": ["production_output_id", "PRODUCTION_OUTPUT_ID"],
        "production_order_id": ["production_order_id", "PRODUCTION_ORDER_ID"],
        "input_material_id": ["input_material_id", "INPUT_MATERIAL_ID"],
        "input_quantity": ["input_quantity", "INPUT_QUANTITY"],
        "output_material_id": ["output_material_id", "OUTPUT_MATERIAL_ID"],
        "output_quantity": ["output_quantity", "OUTPUT_QUANTITY"],
    }
    cleaned = _apply_column_aliases(source_df, aliases)
    cleaned = _trim_string_columns(
        cleaned,
        [
            "production_output_id",
            "production_order_id",
            "input_material_id",
            "input_quantity",
            "output_material_id",
            "output_quantity",
        ],
    )
    cleaned = _filter_non_null_key(cleaned, "production_output_id")
    cleaned = _dedupe_latest(cleaned, "production_output_id")
    cleaned = (
        cleaned.withColumn("input_quantity", _parse_positive_quantity("input_quantity"))
        .withColumn("output_quantity", _parse_positive_quantity("output_quantity"))
    )
    cleaned = cleaned.filter(
        col("input_quantity").isNotNull() & col("output_quantity").isNotNull()
    )
    cleaned = _enforce_foreign_key(
        cleaned, "production_order_id", production_orders_df, "production_order_id"
    )
    valid_raw_materials = (
        materials_df.filter(col("material_type") == "RAW_MATERIAL")
        .select(col("material_id").alias("input_material_id"))
        .distinct()
    )
    valid_finished_goods = (
        materials_df.filter(col("material_type") == "FINISHED_GOOD")
        .select(col("material_id").alias("output_material_id"))
        .distinct()
    )
    cleaned = cleaned.join(valid_raw_materials, on="input_material_id", how="inner")
    return cleaned.join(valid_finished_goods, on="output_material_id", how="inner")


def _clean_machine_downtime(source_df: DataFrame, plants_df: DataFrame) -> DataFrame:
    """Clean machine downtime events from ServiceNow ingest."""
    cleaned = source_df
    if "_databricks_deleted" in cleaned.columns:
        cleaned = cleaned.filter(
            col("_databricks_deleted").isNull() | (col("_databricks_deleted") == lit(False))
        )

    aliases = {
        "downtime_id": ["u_downtime_id", "downtime_id"],
        "plant_id": ["u_plant_id", "plant_id"],
        "machine_name": ["u_machine_name", "machine_name"],
        "start_time": ["u_start_time", "start_time"],
        "end_time": ["u_end_time", "end_time"],
        "reason": ["u_reason", "reason"],
    }
    cleaned = _apply_column_aliases(cleaned, aliases)
    cleaned = _trim_string_columns(
        cleaned,
        ["downtime_id", "plant_id", "machine_name", "reason"],
    )
    cleaned = _filter_non_null_key(cleaned, "downtime_id")
    cleaned = _dedupe_latest(cleaned, "downtime_id")
    cleaned = (
        cleaned.withColumn("machine_name", trim(col("machine_name")))
        .withColumn("reason", upper(trim(col("reason"))))
        .withColumn("start_time", to_timestamp(col("start_time")))
        .withColumn("end_time", to_timestamp(col("end_time")))
    )
    cleaned = cleaned.filter(col("start_time").isNotNull() & col("end_time").isNotNull())
    cleaned = cleaned.withColumn(
        "reason",
        when(col("reason").isin(*VALID_DOWNTIME_REASONS), col("reason")).otherwise(
            upper(col("reason"))
        ),
    )
    return _enforce_foreign_key(cleaned, "plant_id", plants_df, "plant_id")
